const body = $json.body ?? $json;
const slug = (body.project_slug ?? '').toString().trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!slug) throw new Error('project_slug is required in the JSON body.');
const regenRaw = (body.regen_ids ?? '').toString();
const regenIds = regenRaw.split(/[,\s]+/).map((x) => x.trim().toLowerCase()).filter(Boolean);
const DEFAULT_TTS = 'google/gemini-3.1-flash-tts-preview';
const modelRaw = (body.tts_model ?? '').toString().trim();
const ttsModel = /^[a-z0-9][a-z0-9/_.:-]{2,80}$/i.test(modelRaw) ? modelRaw : DEFAULT_TTS;
return [{ json: { slug, regen_ids: regenIds, tts_model: ttsModel } }];

const srcs = $('Split Lines').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const line = srcs[i].json;
  let buf = null;
  try { buf = await this.helpers.getBinaryDataBuffer(i, 'data'); } catch (e) {}
  if (buf && buf.length) {
    out.push({ json: { slug: line.slug, shotId: line.shotId, lineId: line.lineId, fmt: line.fmt ?? 'mp3', audioB64: buf.toString('base64') } });
  } else {
    // Provider returned no audio (e.g. Gemini TTS empty stream on styled input).
    // Mark the line for one bare-text retry instead of failing the whole run.
    out.push({ json: { fallback: true, slug: line.slug, shotId: line.shotId, lineId: line.lineId, fmt: line.fmt ?? 'mp3', text: line.text, voice: line.voice, tts_model: line.tts_model } });
  }
}
return out;

const srcs = $('Needs Fallback?').all(0);
const out = [];
for (let i = 0; i < items.length; i++) {
  const line = srcs[i].json;
  let buf = null;
  try { buf = await this.helpers.getBinaryDataBuffer(i, 'data'); } catch (e) {}
  if (!buf || !buf.length) {
    throw new Error('TTS returned no audio for line ' + (line.lineId ?? i) + ' even without style instructions');
  }
  out.push({ json: { slug: line.slug, shotId: line.shotId, lineId: line.lineId, fmt: line.fmt ?? 'mp3', audioB64: buf.toString('base64') } });
}
return out;
